fn show_double(n: i32) {
    println!("Double of {n} is {}", n * 2);
}

fn main() {
    show_double(4);
    show_double(10);
}

fn area(width: i32, height: i32) -> i32 {
    width * height
}

fn main() {
    let room = area(4, 5);
    println!("The room is {room} square metres");
}

